        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.6.2": "cd",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.0": "Spænding: volt (V).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.1": "Modstand: ohm (\\u03a9).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.2": "Effekt: watt (W).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.3": "Energi: joule (J).",
