        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.6": "Frekvens: hertz (Hz).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.title": "Decimalpræfikser",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.headers.0": "Præfiks",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.headers.1": "Symbol",
