        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.0.0": "kilo",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.0.1": "k",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.0.2": "1.000 = 10^3",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.1.0": "mega",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.1.1": "M",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.1.2": "1.000.000 = 10^6",
