        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.1.2": "1,000,000 = 10^6",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.2.0": "毫",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.2.1": "米",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.2.2": "0.001 = 10^-3",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.1.table.rows.3.0": "微",
