        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.5.0": "cantidad de sustancia",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.5.1": "lunar",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.5.2": "moles",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.6.0": "Intensidad luminosa",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.6.1": "candela",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.6.2": "cd",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.0": "Voltaje: voltio (V).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.1": "Resistencia: ohmios (\\u03a9).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.2": "Potencia: vatio (W).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.3": "Energía: julio (J).",
