        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.table.rows.6.2": "CD",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.0": "Tensão: volts (V).",
        "catalog.concepts.concept-si-system-and-imperial-units.sections.0.bullets.1": "Resistência: ohm (\\u03a9).",
